from qiskit import QuantumCircuit
from math import pi

qc = QuantumCircuit(4)

qubits = [1, 2, 3, 0]  # logical LSB -> MSB

for p in range(3, -1, -1):
    qc.h(qubits[p])
    for q in range(p - 1, -1, -1):
        qc.cp(-pi / (2 ** (p - q)), qubits[q], qubits[p])

for i in range(2):
    qc.swap(qubits[i], qubits[3 - i])
